<script lang="ts">
	import { onMount } from 'svelte';

	interface Props {
		userName?: string;
		onFinish?: () => void;
	}

	let { userName = '', onFinish }: Props = $props();

	// Tampilan nama pengguna: jika kosong gunakan fallback '(Users)' persis desain referensi
	let displayName = $derived(userName && userName.trim().length > 0 ? userName.trim() : '(Users)');

	onMount(() => {
		// Auto-redirect setelah jeda 2.5 detik sesuai spesifikasi
		// Dalam mode dev, ?noredirect=true dapat digunakan untuk inspeksi visual tanpa jeda redirect
		const isNoRedirect =
			import.meta.env.DEV &&
			typeof window !== 'undefined' &&
			window.location.search.includes('noredirect=true');

		if (!isNoRedirect) {
			const timer = setTimeout(() => {
				if (onFinish) {
					onFinish();
				}
			}, 2500);

			return () => {
				clearTimeout(timer);
			};
		}
	});
</script>

